'use strict';

// OpenWorkdays MCP server — remote, anonymous, zero-signup.
// Single zero-dependency Node serverless function. Implements the MCP
// Streamable HTTP transport in STATELESS JSON mode: every POST gets a single
// application/json JSON-RPC 2.0 response. No sessions, no SSE streaming.
//
// Lets autonomous AI agents call OpenWorkdays as a tool with no account/key —
// an agent has no human to do a signup.

const DEFAULT_PROTOCOL_VERSION = '2025-06-18';
const UPSTREAM = 'https://openworkdays.vercel.app/api/businessdays';

const SERVER_INFO = { name: 'openworkdays', version: '0.1.0' };

const BUSINESSDAYS_TOOL = {
  name: 'businessdays',
  description:
    'Business-day date math. Three modes inferred from params: add ' +
    '(start+days -> the date N business days away, negative days = before), ' +
    'diff (start+end -> count of business days between, inclusive of both ' +
    'endpoints), is (date -> is it a business day). Optional weekend ' +
    '(default sat,sun) and holidays (comma list of YYYY-MM-DD you supply). ' +
    'No signup, no API key. Pure UTC date-only math; no ' +
    'time-of-day/DST/timezone.',
  inputSchema: {
    type: 'object',
    properties: {
      start: {
        type: 'string',
        description: 'Start date YYYY-MM-DD (add & diff modes)',
      },
      days: {
        type: 'integer',
        description:
          'Business days to add (add mode); negative subtracts',
      },
      end: {
        type: 'string',
        description: 'End date YYYY-MM-DD (diff mode)',
      },
      date: {
        type: 'string',
        description: 'Date YYYY-MM-DD to test (is mode)',
      },
      weekend: {
        type: 'string',
        description: 'Comma list of weekend days, e.g. "sat,sun" (default sat,sun)',
      },
      holidays: {
        type: 'string',
        description: 'Comma list of YYYY-MM-DD dates treated as non-working',
      },
    },
  },
  annotations: {
    readOnlyHint: true,
    openWorldHint: false,
    destructiveHint: false,
    idempotentHint: true,
  },
};

// --- helpers ---------------------------------------------------------------
function readBody(req) {
  return new Promise((resolve) => {
    // Vercel may have already parsed/buffered the body.
    if (req.body !== undefined && req.body !== null) {
      if (typeof req.body === 'string') {
        try {
          resolve(req.body.length ? JSON.parse(req.body) : undefined);
        } catch (e) {
          resolve({ __parseError: true });
        }
        return;
      }
      if (Buffer.isBuffer(req.body)) {
        const s = req.body.toString('utf8');
        try {
          resolve(s.length ? JSON.parse(s) : undefined);
        } catch (e) {
          resolve({ __parseError: true });
        }
        return;
      }
      if (typeof req.body === 'object') {
        resolve(req.body);
        return;
      }
    }
    // Otherwise read the raw stream.
    let data = '';
    let done = false;
    const finish = (val) => {
      if (done) return;
      done = true;
      resolve(val);
    };
    try {
      req.on('data', (chunk) => {
        data += chunk;
      });
      req.on('end', () => {
        if (!data.length) return finish(undefined);
        try {
          finish(JSON.parse(data));
        } catch (e) {
          finish({ __parseError: true });
        }
      });
      req.on('error', () => finish({ __parseError: true }));
    } catch (e) {
      finish({ __parseError: true });
    }
  });
}

function jsonRpcError(id, code, message, data) {
  const err = { code, message };
  if (data !== undefined) err.data = data;
  return { jsonrpc: '2.0', id: id === undefined ? null : id, error: err };
}

function jsonRpcResult(id, result) {
  return { jsonrpc: '2.0', id, result };
}

function toolResult(text, structuredContent, isError) {
  const r = { content: [{ type: 'text', text }], isError: !!isError };
  if (structuredContent !== undefined) r.structuredContent = structuredContent;
  return r;
}

async function callBusinessdays(args) {
  try {
    const qs = new URLSearchParams();
    const keys = ['start', 'days', 'end', 'date', 'weekend', 'holidays'];
    for (let i = 0; i < keys.length; i++) {
      const k = keys[i];
      const v = args[k];
      if (v === undefined || v === null || v === '') continue;
      qs.set(k, String(v));
    }
    const r = await fetch(UPSTREAM + '?' + qs.toString(), {
      headers: { Accept: 'application/json' },
    });
    let j;
    try {
      j = await r.json();
    } catch (e) {
      const txt = '{"error":"upstream returned non-JSON"}';
      j = JSON.parse(txt);
    }
    const isError =
      !r.ok || (j && typeof j === 'object' && j.error != null);
    return toolResult(JSON.stringify(j, null, 2), j, isError);
  } catch (e) {
    return toolResult(
      'businessdays upstream request failed: ' +
        (e && e.message ? e.message : 'error'),
      undefined,
      true
    );
  }
}

// Process a single JSON-RPC message. Returns:
//  - a JSON-RPC response object (for requests), or
//  - null (for notifications — no response).
async function handleMessage(msg) {
  if (!msg || typeof msg !== 'object' || Array.isArray(msg)) {
    return jsonRpcError(null, -32600, 'Invalid Request: expected a JSON-RPC object');
  }

  const { id, method } = msg;
  const params = msg.params;
  const isNotification = id === undefined || id === null;

  if (typeof method !== 'string') {
    if (isNotification) return null;
    return jsonRpcError(id, -32600, 'Invalid Request: missing method');
  }

  // Any notifications/* message → no response (handled as HTTP 202 by caller).
  if (method.indexOf('notifications/') === 0) {
    return null;
  }

  if (method === 'initialize') {
    const reqProto =
      params && typeof params.protocolVersion === 'string'
        ? params.protocolVersion
        : DEFAULT_PROTOCOL_VERSION;
    return jsonRpcResult(id, {
      protocolVersion: reqProto,
      capabilities: { tools: {} },
      serverInfo: SERVER_INFO,
    });
  }

  if (method === 'ping') {
    return jsonRpcResult(id, {});
  }

  if (method === 'tools/list') {
    return jsonRpcResult(id, { tools: [BUSINESSDAYS_TOOL] });
  }

  if (method === 'tools/call') {
    if (!params || typeof params !== 'object') {
      return jsonRpcError(id, -32602, 'Invalid params: expected an object');
    }
    const name = params.name;
    const args = params.arguments || {};

    if (name !== 'businessdays') {
      return jsonRpcResult(
        id,
        toolResult(
          'Unknown tool "' +
            String(name) +
            '". This server exposes exactly one tool: "businessdays". ' +
            'Call tools/list to see its schema.',
          undefined,
          true
        )
      );
    }

    if (
      !args ||
      typeof args !== 'object' ||
      Array.isArray(args) ||
      Object.keys(args).length === 0
    ) {
      return jsonRpcResult(
        id,
        toolResult(
          'Provide at least one mode: add needs start+days, diff needs ' +
            'start+end, is needs date. See https://openworkdays.vercel.app',
          undefined,
          true
        )
      );
    }

    const result = await callBusinessdays(args);
    return jsonRpcResult(id, result);
  }

  // Unknown method
  if (isNotification) return null;
  return jsonRpcError(id, -32601, 'Method not found: ' + String(method));
}

// --- handler ---------------------------------------------------------------
module.exports = async (req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'POST, OPTIONS, GET');
  res.setHeader(
    'Access-Control-Allow-Headers',
    'Content-Type, MCP-Protocol-Version, Mcp-Session-Id'
  );

  const ip = (req.headers['x-forwarded-for'] || '').split(',')[0];
  const ua = req.headers['user-agent'] || null;

  if (req.method === 'OPTIONS') {
    res.statusCode = 204;
    return res.end();
  }

  res.setHeader('Content-Type', 'application/json');

  if (req.method === 'GET') {
    console.log(
      JSON.stringify({ evt: 'mcp_hit', method: 'GET', ip, ua, ts: Date.now() })
    );
    res.statusCode = 405;
    return res.end(
      JSON.stringify({
        error: 'Use POST for MCP JSON-RPC',
        endpoint: 'https://openworkdays.vercel.app/api/mcp',
      })
    );
  }

  if (req.method !== 'POST') {
    console.log(
      JSON.stringify({
        evt: 'mcp_hit',
        method: req.method || null,
        ip,
        ua,
        ts: Date.now(),
      })
    );
    res.statusCode = 405;
    return res.end(
      JSON.stringify({
        error: 'Use POST for MCP JSON-RPC',
        endpoint: 'https://openworkdays.vercel.app/api/mcp',
      })
    );
  }

  const body = await readBody(req);

  // Parse error → -32700
  if (body && body.__parseError) {
    console.log(
      JSON.stringify({
        evt: 'mcp_hit',
        method: 'parse_error',
        ip,
        ua,
        ts: Date.now(),
      })
    );
    res.statusCode = 200;
    return res.end(
      JSON.stringify(jsonRpcError(null, -32700, 'Parse error: invalid JSON'))
    );
  }

  // --- Batch (array of messages) -------------------------------------------
  if (Array.isArray(body)) {
    console.log(
      JSON.stringify({
        evt: 'mcp_hit',
        method: 'batch',
        ip,
        ua,
        ts: Date.now(),
      })
    );
    if (body.length === 0) {
      res.statusCode = 200;
      return res.end(
        JSON.stringify(jsonRpcError(null, -32600, 'Invalid Request: empty batch'))
      );
    }
    const responses = [];
    for (let i = 0; i < body.length; i++) {
      // eslint-disable-next-line no-await-in-loop
      const r = await handleMessage(body[i]);
      if (r !== null) responses.push(r);
    }
    if (responses.length === 0) {
      // All notifications → no response bodies.
      res.statusCode = 202;
      return res.end();
    }
    res.statusCode = 200;
    return res.end(JSON.stringify(responses));
  }

  // --- Single message (common case) ----------------------------------------
  if (!body || typeof body !== 'object') {
    console.log(
      JSON.stringify({
        evt: 'mcp_hit',
        method: 'invalid_request',
        ip,
        ua,
        ts: Date.now(),
      })
    );
    res.statusCode = 200;
    return res.end(
      JSON.stringify(
        jsonRpcError(null, -32600, 'Invalid Request: expected a JSON-RPC object')
      )
    );
  }

  const method = typeof body.method === 'string' ? body.method : null;
  console.log(
    JSON.stringify({ evt: 'mcp_hit', method, ip, ua, ts: Date.now() })
  );

  const response = await handleMessage(body);

  // Notification → HTTP 202, no JSON-RPC body.
  if (response === null) {
    res.statusCode = 202;
    return res.end();
  }

  res.statusCode = 200;
  return res.end(JSON.stringify(response));
};

'use strict';

// OpenWorkdays v0.1 — anonymous, zero-signup business-day date-arithmetic API.
// Single zero-dependency Node serverless function. Pure UTC date math only.

// --- In-memory per-instance best-effort IP rate limiter ---------------------
// NOTE: This is per-instance / best-effort only. Serverless instances are
// ephemeral and not shared, so this is a soft abuse brake, NOT a guarantee.
const RL_WINDOW_SEC = 600;
const RL_MAX = 120;
const rlMap = new Map(); // ip -> number[] (timestamps in ms)

function rateLimit(ip) {
  const now = Date.now();
  const windowMs = RL_WINDOW_SEC * 1000;
  const hits = (rlMap.get(ip) || []).filter((t) => now - t < windowMs);
  hits.push(now);
  rlMap.set(ip, hits);
  if (hits.length > RL_MAX) {
    const oldest = hits[0];
    const retryAfterSec = Math.max(1, Math.ceil((windowMs - (now - oldest)) / 1000));
    return { limited: true, retryAfterSec };
  }
  return { limited: false };
}

// --- Date helpers -----------------------------------------------------------
const DAY = 86400000;
const WD = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];

// Parse YYYY-MM-DD strictly into UTC ms, or null if invalid.
function isoToUTC(s) {
  if (typeof s !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return null;
  const y = +s.slice(0, 4);
  const m = +s.slice(5, 7);
  const d = +s.slice(8, 10);
  if (y < 1000 || y > 9999) return null;
  const ms = Date.UTC(y, m - 1, d);
  const dt = new Date(ms);
  if (
    dt.getUTCFullYear() !== y ||
    dt.getUTCMonth() !== m - 1 ||
    dt.getUTCDate() !== d
  ) {
    return null;
  }
  return ms;
}

function toISO(ms) {
  const dt = new Date(ms);
  const y = String(dt.getUTCFullYear()).padStart(4, '0');
  const m = String(dt.getUTCMonth() + 1).padStart(2, '0');
  const d = String(dt.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

function isWorking(ms, weekendSet, holidaySet) {
  const d = new Date(ms).getUTCDay();
  if (weekendSet.has(d)) return false;
  if (holidaySet.has(toISO(ms))) return false;
  return true;
}

const WEEKEND_TOKENS = {
  sun: 0,
  mon: 1,
  tue: 2,
  wed: 3,
  thu: 4,
  fri: 5,
  sat: 6,
};

// --- Handler ----------------------------------------------------------------
module.exports = async (req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Content-Type', 'application/json');
  res.setHeader('Access-Control-Allow-Methods', 'GET, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.statusCode = 204;
    return res.end();
  }
  if (req.method !== 'GET') {
    res.statusCode = 405;
    return res.end(JSON.stringify({ error: 'method not allowed' }));
  }

  const ip = (req.headers['x-forwarded-for'] || 'ip').split(',')[0].trim() || 'ip';

  const logHit = (mode, ok) => {
    try {
      console.log(
        JSON.stringify({
          evt: 'workdays_hit',
          mode: mode || null,
          ip,
          ua: req.headers['user-agent'] || null,
          ok: !!ok,
          ts: Date.now(),
        })
      );
    } catch (e) {
      /* ignore logging errors */
    }
  };

  // Rate limit
  const rl = rateLimit(ip);
  if (rl.limited) {
    logHit(null, false);
    res.statusCode = 429;
    res.setHeader('Retry-After', String(rl.retryAfterSec));
    return res.end(
      JSON.stringify({ error: 'rate limited', retryAfterSec: rl.retryAfterSec })
    );
  }

  // Parse query (prefer req.query, fallback to URL parsing).
  const q = (name) => {
    try {
      if (req.query && Object.prototype.hasOwnProperty.call(req.query, name)) {
        const v = req.query[name];
        return Array.isArray(v) ? v[0] : v;
      }
      const u = new URL(req.url, 'http://x');
      return u.searchParams.get(name);
    } catch (e) {
      return null;
    }
  };

  const bad = (mode, obj) => {
    logHit(mode, false);
    res.statusCode = 400;
    return res.end(JSON.stringify(obj));
  };

  // --- Shared params: weekend ----------------------------------------------
  const weekendRaw = q('weekend');
  const weekendSet = new Set();
  {
    const src =
      weekendRaw == null || weekendRaw === '' ? 'sat,sun' : String(weekendRaw);
    const toks = src.split(',');
    for (let i = 0; i < toks.length; i++) {
      const tok = toks[i].trim();
      if (tok === '') continue;
      const low = tok.toLowerCase();
      if (Object.prototype.hasOwnProperty.call(WEEKEND_TOKENS, low)) {
        weekendSet.add(WEEKEND_TOKENS[low]);
      } else if (/^[0-6]$/.test(tok)) {
        weekendSet.add(+tok);
      } else {
        return bad(null, { error: 'invalid weekend token', value: tok });
      }
    }
    if (weekendSet.size >= 7) {
      return bad(null, { error: 'weekend cannot include all 7 weekdays' });
    }
  }

  // --- Shared params: holidays ---------------------------------------------
  const holidaysRaw = q('holidays');
  const holidaySet = new Set();
  if (holidaysRaw != null && holidaysRaw !== '') {
    const toks = String(holidaysRaw).split(',');
    const cleaned = [];
    for (let i = 0; i < toks.length; i++) {
      const tok = toks[i].trim();
      if (tok === '') continue;
      cleaned.push(tok);
    }
    if (cleaned.length > 1000) {
      return bad(null, { error: 'too many holidays (max 1000)' });
    }
    for (let i = 0; i < cleaned.length; i++) {
      const tok = cleaned[i];
      const ms = isoToUTC(tok);
      if (ms == null) {
        return bad(null, { error: 'invalid holiday date', value: tok });
      }
      holidaySet.add(toISO(ms));
    }
  }

  const weekendOut = Array.from(weekendSet)
    .sort((a, b) => a - b)
    .map((i) => WD[i]);

  // --- Mode resolution ------------------------------------------------------
  const daysParam = q('days');
  const endParam = q('end');
  const dateParam = q('date');
  const startParam = q('start');

  let mode;
  if (daysParam != null) {
    mode = 'add';
  } else if (endParam != null) {
    mode = 'diff';
  } else if (dateParam != null) {
    mode = 'is';
  } else {
    return bad(null, {
      error: 'specify a mode',
      usage: {
        add: '?start=YYYY-MM-DD&days=N[&weekend=sat,sun][&holidays=YYYY-MM-DD,...]',
        diff: '?start=YYYY-MM-DD&end=YYYY-MM-DD[&weekend=][&holidays=]',
        is: '?date=YYYY-MM-DD[&weekend=][&holidays=]',
      },
      docs: 'https://openworkdays.vercel.app',
    });
  }

  try {
    if (mode === 'add') {
      if (startParam == null) return bad('add', { error: 'missing start' });
      const startMs = isoToUTC(startParam);
      if (startMs == null) {
        return bad('add', {
          error: 'invalid date',
          param: 'start',
          value: startParam,
        });
      }
      if (!/^[+-]?\d+$/.test(String(daysParam))) {
        return bad('add', { error: 'invalid days (must be integer)' });
      }
      const N = parseInt(daysParam, 10);
      if (Math.abs(N) > 10000) {
        return bad('add', { error: 'days out of range (max 10000)' });
      }

      let result;
      if (N === 0) {
        result = startMs;
      } else {
        let cursor = startMs;
        let rem = Math.abs(N);
        const step = N > 0 ? DAY : -DAY;
        const cap = Math.abs(N) * 7 + 14;
        let iter = 0;
        while (rem > 0) {
          if (++iter > cap) {
            throw new Error('compute guard');
          }
          cursor += step;
          if (isWorking(cursor, weekendSet, holidaySet)) rem--;
        }
        result = cursor;
      }

      logHit('add', true);
      res.statusCode = 200;
      return res.end(
        JSON.stringify({
          mode: 'add',
          start: toISO(startMs),
          days: N,
          result: toISO(result),
          resultWeekday: WD[new Date(result).getUTCDay()],
          startIsBusinessDay: isWorking(startMs, weekendSet, holidaySet),
          weekend: weekendOut,
          holidaysApplied: holidaySet.size,
          engine: 'date-utc-v0.1',
          computedAt: new Date().toISOString(),
        })
      );
    }

    if (mode === 'diff') {
      if (startParam == null) return bad('diff', { error: 'missing start' });
      const startMs = isoToUTC(startParam);
      if (startMs == null) {
        return bad('diff', {
          error: 'invalid date',
          param: 'start',
          value: startParam,
        });
      }
      const endMs = isoToUTC(endParam);
      if (endMs == null) {
        return bad('diff', {
          error: 'invalid date',
          param: 'end',
          value: endParam,
        });
      }
      const lo = Math.min(startMs, endMs);
      const hi = Math.max(startMs, endMs);
      const spanDays = (hi - lo) / DAY;
      if (spanDays > 36600) {
        return bad('diff', { error: 'date range too large (max 36600 days)' });
      }
      let count = 0;
      for (let ms = lo; ms <= hi; ms += DAY) {
        if (isWorking(ms, weekendSet, holidaySet)) count++;
      }
      const sign = endMs < startMs ? -1 : 1;
      const businessDays = count * sign;

      logHit('diff', true);
      res.statusCode = 200;
      return res.end(
        JSON.stringify({
          mode: 'diff',
          start: toISO(startMs),
          end: toISO(endMs),
          businessDays,
          inclusive: 'both endpoints',
          weekend: weekendOut,
          holidaysApplied: holidaySet.size,
          engine: 'date-utc-v0.1',
          computedAt: new Date().toISOString(),
        })
      );
    }

    // mode === 'is'
    const dateMs = isoToUTC(dateParam);
    if (dateMs == null) {
      return bad('is', {
        error: 'invalid date',
        param: 'date',
        value: dateParam,
      });
    }
    const d = new Date(dateMs).getUTCDay();
    const weekendHit = weekendSet.has(d);
    const holidayHit = holidaySet.has(toISO(dateMs));
    const isBiz = !weekendHit && !holidayHit;
    const reason = weekendHit ? 'weekend' : holidayHit ? 'holiday' : null;

    logHit('is', true);
    res.statusCode = 200;
    return res.end(
      JSON.stringify({
        mode: 'is',
        date: toISO(dateMs),
        weekday: WD[d],
        isBusinessDay: isBiz,
        reason,
        weekend: weekendOut,
        holidaysApplied: holidaySet.size,
        engine: 'date-utc-v0.1',
        computedAt: new Date().toISOString(),
      })
    );
  } catch (e) {
    logHit(mode, false);
    res.statusCode = 500;
    return res.end(JSON.stringify({ error: 'internal compute guard' }));
  }
};

'use strict';

// Zero-dependency test harness for api/businessdays.js.
// Drives the handler with a fake req/res, asserts on parsed JSON.

const handler = require('../api/businessdays.js');

function makeRes() {
  return {
    statusCode: 200,
    _body: '',
    setHeader() {},
    end(body) {
      this._body = body == null ? '' : String(body);
      return this;
    },
  };
}

async function call(qs) {
  const req = {
    method: 'GET',
    headers: {},
    url: '/api/businessdays' + (qs ? '?' + qs : ''),
  };
  const res = makeRes();
  await handler(req, res);
  let json = null;
  try {
    json = res._body ? JSON.parse(res._body) : null;
  } catch (e) {
    json = null;
  }
  return { status: res.statusCode, json };
}

const cases = [
  {
    qs: 'start=2026-05-15&days=1',
    check: (r) =>
      r.status === 200 &&
      r.json.result === '2026-05-18' &&
      r.json.resultWeekday === 'mon',
  },
  {
    qs: 'start=2026-05-15&days=5',
    check: (r) => r.status === 200 && r.json.result === '2026-05-22',
  },
  {
    qs: 'start=2026-05-15&days=1&holidays=2026-05-18',
    check: (r) => r.status === 200 && r.json.result === '2026-05-19',
  },
  {
    qs: 'start=2026-05-15&days=0',
    check: (r) => r.status === 200 && r.json.result === '2026-05-15',
  },
  {
    qs: 'start=2026-05-18&days=-1',
    check: (r) => r.status === 200 && r.json.result === '2026-05-15',
  },
  {
    qs: 'start=2026-05-15&end=2026-05-22',
    check: (r) => r.status === 200 && r.json.businessDays === 6,
